test("workflow retry limit overrides accept zero and reject malformed values", () => {
	assert.equal(
		resolveWorkflowRetryLimit(TRANSIENT_MODEL_FAILURE_RETRIES_ENV, 5, {
			[TRANSIENT_MODEL_FAILURE_RETRIES_ENV]: "0",
		}),
		0,
	);
	assert.equal(
		resolveWorkflowRetryLimit(ARTIFACT_OUTPUT_RETRIES_ENV, 2, {}),
		2,
	);
	assert.throws(
		() =>
			resolveWorkflowRetryLimit(ARTIFACT_OUTPUT_RETRIES_ENV, 2, {
				[ARTIFACT_OUTPUT_RETRIES_ENV]: "-1",
			}),
		/non-negative safe integer/,
	);
	assert.throws(
		() =>
			resolveWorkflowRetryLimit(TRANSIENT_MODEL_FAILURE_RETRIES_ENV, 5, {
				[TRANSIENT_MODEL_FAILURE_RETRIES_ENV]: "1.5",
			}),
		/non-negative safe integer/,
	);
});

test("compactStrings trims, filters, and optionally preserves duplicates", () => {
	assert.deepEqual(compactStrings([" alpha ", "", "alpha", " beta ", null]), [
		"alpha",
		"beta",
	]);
	assert.deepEqual(compactStrings([" a ", " a ", ""], { unique: false }), [
		"a",
		"a",
	]);
	assert.deepEqual(
		compactStrings([" ", "x", "x"], {
			trim: false,
			unique: false,
			dropEmpty: false,
			dropWhitespaceOnly: false,
		}),
		[" ", "x", "x"],
	);
});

test("blocked dependencies skip only dependent pending tasks", () => {
	const run = {
		tasks: [
			{
				specId: "gate.main",
				status: "blocked",
				statusDetail: "needs_attention",
			},
			{
				specId: "dependent.main",
				status: "pending",
				statusDetail: "pending",
			},
			{
				specId: "independent.main",
				status: "pending",
				statusDetail: "pending",
			},
		],
	};
	const compiledFlow = {
		type: WORKFLOW_RUN_TYPE,
		stages: [],
		tasks: [
			{ id: "gate.main" },
			{ id: "dependent.main", dependsOn: ["gate.main"] },
			{ id: "independent.main" },
		],
	};

	assert.equal(markDagDependentsSkipped(run, compiledFlow), true);
	assert.equal(run.tasks[1].status, "skipped");
	assert.equal(run.tasks[1].statusDetail, "skipped_after_dependency_failure");
	assert.equal(run.tasks[2].status, "pending");
});

test("fail-fast flags on cancel pending siblings and interrupt running siblings distinctly", async () => {
	const cwd = makeProject();
	const interrupts = [];
	try {
		setSubagentApiForTests({
			async runSubagent() {
				throw new Error("unexpected launch");
			},
			async getSubagentStatus() {
				return null;
			},
			async reconcileSubagentRun() {
				return {};
			},
			async interruptSubagent(options) {
				interrupts.push(options);
				return {};
			},
		});
		const { run } = await createFailFastPolicyRun(cwd, {
			failFast: true,
			cancelSiblingsOnFailure: true,
			cancelDescendantsOnParentFailure: true,
		});

		await scheduleRun(cwd, run.runId);
		const updated = await readRunRecord(cwd, run.runId);
		for (const specId of [
			"running.main",
			"pending.main",
			"partial-child.main",
		]) {
			const task = taskBySpec(updated, specId);
			assert.equal(task.status, "interrupted", specId);
			assert.equal(task.statusDetail, "fail_fast_cancelled", specId);
		}
		assert.equal(taskBySpec(updated, "require-child.main").status, "skipped");
		assert.equal(
			taskBySpec(updated, "require-child.main").statusDetail,
			"skipped_after_dependency_failure",
		);
		assert.equal(interrupts.length, 1);
		assert.equal(interrupts[0].runId, "child-running");
		assert.equal(interrupts[0].reason, "workflow fail-fast cancellation");
		assert.deepEqual(summarizeTaskFailureClasses(updated.tasks), {
			failed: 1,
			failFastCancelled: 3,
			otherInterrupted: 0,
		});
		assert.match(
			formatRun(updated),
			/failureClasses=failed=1, failFastCancelled=3, otherInterrupted=0/,
		);
	} finally {
		setSubagentApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("deep-research tiered verification variant is path-ref opt-in", async () => {
	const specPath = join(
		process.cwd(),
		"workflows",
		"deep-research",
		"tiered-verification.spec.json",
	);
	const spec = parsePublicWorkflow(JSON.parse(readFileSync(specPath, "utf8")));
	const compiled = await compileWorkflow(spec, {
		cwd: process.cwd(),
		task: "Research the deep-research artifact contract.",
		specPath,
	});
	const byStage = new Map(compiled.tasks.map((task) => [task.stageId, task]));
	const verificationTiers = byStage.get("verification-tiers");
	const verifyCore = byStage.get("verify-core-claims");
	const verifyTail = byStage.get("verify-tail-claims");
	const auditClaims = byStage.get("audit-claims");

	assert.equal(spec.name, "deep-research-tiered-verification-opt-in");
	assert.equal(verificationTiers?.kind, "support");
	assert.deepEqual(verificationTiers.dependsOn, ["sanitize-claims.main"]);
	assert.equal(
		verificationTiers.support.uses,
		"./helpers/tier-verification-candidates.mjs",
	);
	assert.deepEqual(verificationTiers.support.options, { coreTierSize: 8 });
	for (const [stage, path, thinking] of [
		[verifyCore, "$.coreCandidates", "high"],
		[verifyTail, "$.tailCandidates", "medium"],
	]) {
		assert.deepEqual(stage?.dependsOn, ["verification-tiers.main"]);
		assert.deepEqual(stage?.foreach?.from, {
			stage: "verification-tiers",
			path,
		});
		assert.equal(stage?.runtime.thinking, thinking);
		assert.ok(
			stage?.artifactGraph.output.controlSchemaPath.endsWith(
				join(
					"workflows",
					"deep-research",
					"schemas",
					"deep-research-verify-claims-control.schema.json",
				),
			),
		);
		assert.equal(stage?.artifactGraph.artifactAccess, "none");
	}
	// Both single-claim verifier stages keep the default one-claim prompt, not
	// the batched results[] carrier.
	assert.doesNotMatch(verifyCore?.compiledPrompt ?? "", /results\[\]/);
	assert.doesNotMatch(verifyTail?.compiledPrompt ?? "", /results\[\]/);
	// The audit gate must see all verifier outputs from both tiers. The
	// verification-tiers planning stage is intentionally not an audit source:
	// the gate's fallback verifier-row collection would otherwise misread its
	// candidate arrays as verdict rows.
	assert.deepEqual(auditClaims?.dependsOn, [
		"plan.main",
		"normalize-input-packet.main",
		"normalize-claims.main",
		"sanitize-claims.main",
		"verify-core-claims.item",
		"verify-tail-claims.item",
	]);
	assert.equal(byStage.has("verify-claims"), false);
	assert.equal(byStage.has("verification-batches"), false);
	assert.equal(byStage.has("verification-shadow-selector"), false);
});

test("deep-research verification candidate sanitizer demotes non-verifiable candidates", async () => {
	const { default: helper } = await import(
		`../../workflows/deep-research/helpers/sanitize-verification-candidates.mjs?test=${Date.now()}`
	);
	const result = await helper({
		sources: {
			"normalize-input-packet.main": {
				packet: {
					research: {
						extractedFacts: [
							{
								slotId: "slot-001",
								value:
									"OWASP documents indirect prompt injection from external content.",
								sourceRefs: ["wsrc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"],
								sourceUrls: ["https://example.test/owasp"],
								sourceTitleOrPublisher: "OWASP",
								quote:
									"Indirect prompt injection occurs when LLMs accept external input such as websites or files.",
								sourceQuality: "primary",
							},
						],
					},
				},
			},
			"normalize-claims.main": {
				claimInventory: {
					verificationCandidates: [
						{
							id: "claim-001",
							claim:
								"OWASP documents indirect prompt injection from external content.",
							factSlotIds: ["slot-001"],
							sourceRefs: ["wsrc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"],
						},
						{
							id: "claim-002",
							claim:
								"Named tool capability evidence was fetched from official docs on 2026-07-02, but exact package versions were not reliably extracted from PyPI pages.",
							factSlotIds: ["slot-002"],
							sourceRefs: ["wsrc_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"],
						},
						{
							id: "claim-003",
							claim:
								"A low-overhead small-SaaS baseline can be synthesized from primary controls.",
							factSlotIds: ["slot-003"],
							sourceUrls: ["https://example.test/control"],
						},
						{
							id: "claim-004",
							claim:
								"Provider-specific egress allowlist evidence was not found in inspected sources.",
							factSlotIds: ["slot-004"],
							sourceRefs: ["wsrc_cccccccccccccccccccccccccccccccc"],
						},
					],
					preservedClaims: [
						{ id: "preserved-001", claim: "Existing preserved lead" },
					],
					duplicates: [],
				},
				factSlotCoverage: [
					{
						slotId: "slot-001",
						status: "filled",
						verificationCandidateIds: ["claim-001"],
					},
					{
						slotId: "slot-002",
						status: "filled",
						verificationCandidateIds: ["claim-002"],
					},
				],
				coverageGaps: [],
			},
		},
	});

	assert.equal(
		result.schema,
		"deep-research-verification-candidate-sanitizer-v1",
	);
	assert.deepEqual(
		result.claimInventory.verificationCandidates.map((claim) => claim.id),
		["claim-001"],
	);
	assert.equal(
		result.claimInventory.verificationCandidates[0].verifierInputPolicy,
		"use_sourceRefs_or_sourceUrls_only_do_not_call_workflow_artifact",
	);
	assert.equal(result.sanitizerDiagnostics.sourceEvidenceHintRows, 1);
	assert.deepEqual(
		result.claimInventory.verificationCandidates[0].sourceEvidenceHints.map(
			(hint) => hint.quote,
		),
		[
			"Indirect prompt injection occurs when LLMs accept external input such as websites or files.",
		],
	);
	assert.equal(result.sanitizerDiagnostics.demotedCandidateCount, 3);
	assert.equal(
		result.sanitizerDiagnostics.demotionReasonCounts
			.workflow_context_date_claim,
		1,
	);
	assert.equal(
		result.sanitizerDiagnostics.demotionReasonCounts
			.synthesized_recommendation_claim,
		1,
	);
	assert.equal(
		result.sanitizerDiagnostics.demotionReasonCounts.evidence_gap_claim,
		2,
	);
	assert.deepEqual(
		result.coverageGaps.map((gap) => gap.claimId),
		["claim-002", "claim-003", "claim-004"],
	);
	const slotTwo = result.factSlotCoverage.find(
		(slot) => slot.slotId === "slot-002",
	);
	assert.equal(slotTwo.status, "partial");
	assert.deepEqual(slotTwo.verificationCandidateIds, []);
	assert.match(slotTwo.gapReason, /sanitized verifier candidates: claim-002/);
	assert.ok(
		result.claimInventory.preservedClaims.some(
			(claim) => claim.originalCandidateId === "claim-002",
		),
	);
});

test("deep-research verification candidate sanitizer rewrites mismatched and overclaimed candidates to source atoms", async () => {
	const { default: helper } = await import(
		`../../workflows/deep-research/helpers/sanitize-verification-candidates.mjs?test=${Date.now()}`
	);
	const seccompRef = "wsrc_11111111111111111111111111111111";
	const otelRef = "wsrc_22222222222222222222222222222222";
	const redirectRef = "wsrc_33333333333333333333333333333333";
	const result = await helper({
		sources: {
			"normalize-input-packet.main": {
				packet: {
					research: {
						extractedFacts: [
							{
								slotId: "slot-sandbox",
								value:
									"Docker's default seccomp profile blocks selected Linux system calls for containers.",
								sourceRefs: [seccompRef],
								sourceUrls: ["https://docs.docker.test/seccomp"],
								quote:
									"The default seccomp profile provides a sane default for running containers with seccomp and disables around 44 system calls.",
								sourceQuality: "primary",
							},
							{
								slotId: "slot-audit",
								value:
									"Each span has a trace_id, span_id, parent span ID, start and end timestamps, and attributes.",
								sourceRefs: [otelRef],
								sourceUrls: ["https://opentelemetry.test/traces"],
								quote:
									"Each Span contains a trace ID, span ID, parent span ID, start and end timestamps, and attributes.",
								sourceQuality: "primary",
							},
							{
								slotId: "slot-hitl",
								sourceRefs: [redirectRef],
								sourceUrls: ["https://langchain-ai.test/langgraph/hitl"],
								quote: "Redirecting...",
								sourceQuality: "redirect",
							},
						],
					},
				},
			},
			"normalize-claims.main": {
				claimInventory: {
					verificationCandidates: [
						{
							id: "claim-mismatch",
							claim:
								"Passing --network=none to a Docker container fully disables all network access for that container.",
							factSlotIds: ["slot-sandbox"],
							sourceRefs: [seccompRef],
							sourceUrls: ["https://docs.docker.test/seccomp"],
						},
						{
							id: "claim-overclaim",
							claim:
								"OpenTelemetry spans are the canonical audit log primitive for agent actions and gen_ai.system/gen_ai.request.model attributes provide cross-tool interoperability.",
							factSlotIds: ["slot-audit"],
							sourceRefs: [otelRef],
							sourceUrls: ["https://opentelemetry.test/traces"],
						},
						{
							id: "claim-redirect",
							claim:
								"LangGraph interrupt() pauses graph execution before or after specified nodes for human review.",
							factSlotIds: ["slot-hitl"],
							sourceRefs: [redirectRef],
							sourceUrls: ["https://langchain-ai.test/langgraph/hitl"],
						},
					],
					preservedClaims: [],
					duplicates: [],
				},
				factSlotCoverage: [],
				coverageGaps: [],
			},
		},
		options: {
			overclaimedSourceInferencePhrases: [
				"canonical audit log primitive",
				"gen_ai.system",
				"gen_ai.request.model",
				"interrupt()",
				"before or after specified nodes",
			],
		},
	});

	const rewritten = result.claimInventory.verificationCandidates;
	assert.deepEqual(
		rewritten.map((claim) => claim.id),
		["claim-mismatch", "claim-overclaim"],
	);
	assert.equal(
		rewritten[0].claim,
		"The default seccomp profile provides a sane default for running containers with seccomp and disables around 44 system calls.",
	);
	assert.equal(
		rewritten[1].claim,
		"Each Span contains a trace ID, span ID, parent span ID, start and end timestamps, and attributes.",
	);
	assert.deepEqual(result.sanitizerDiagnostics.rewriteReasonCounts, {
		source_hint_claim_mismatch: 2,
		overclaimed_source_inference: 1,
	});
	assert.equal(
		result.sanitizerDiagnostics.demotionReasonCounts.placeholder_source_hint,
		1,
	);
	assert.deepEqual(result.sanitizerDiagnostics.demotedCandidateIds, [
		"claim-redirect",
	]);
});

