test("deep-review finding-pipeline preserves structured locations through dedup and partition", async () => {
	const helperPath = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"workflows",
		"deep-review",
		"helpers",
		"finding-pipeline.mjs",
	);
	const helper = (await import(pathToFileURL(helperPath).href)).default;

	const exactEvidence = "  return pattern.test(hostname);\r\n\r\n  // keep spacing  ";
	const dedup = await helper({
		sources: {
			"reviewers.lens-a": {
				findings: [
					{
						severity: "high",
						title: "Path boundary bypass in isPathInsideRoot",
						file: "host/src/alpine/rootfs.ts",
						// Line numbers live only in prose evidence here; the pipeline
						// must reconstruct them into structured locations.
						evidence:
							"Gates resolveWritePath (line 46) and assertSafeWritePath (line 90).",
						evidenceQuote: "if (!isPathInsideRoot(target, root)) throw",
					},
					{
						severity: "medium",
						title: "Regex anchor dropped in matchHostname",
						file: "host/src/host/patterns.ts",
						// Explicit structured locations must pass through verbatim.
						locations: [
							{
								file: "host/src/host/patterns.ts",
								line: 15,
								symbol: "matchHostname",
							},
						],
						evidence: "diff drops the $ anchor",
						evidenceQuotes: [
							"return pattern.test(hostname)",
							"diff drops the $ anchor",
							exactEvidence,
						],
					},
				],
			},
		},
		options: { mode: "dedup" },
	});

	const boundary = dedup.findings.find((f) =>
		f.title.includes("Path boundary"),
	);
	// Reconstructed from prose: two distinct line locations on the cited file.
	assert.deepEqual(boundary.locations, [
		{ file: "host/src/alpine/rootfs.ts", line: 46 },
		{ file: "host/src/alpine/rootfs.ts", line: 90 },
	]);
	assert.deepEqual(boundary.evidenceQuotes, [
		"if (!isPathInsideRoot(target, root)) throw",
		"Gates resolveWritePath (line 46) and assertSafeWritePath (line 90).",
	]);
	const regex = dedup.findings.find((f) => f.title.includes("Regex anchor"));
	// Explicit location preserved verbatim, including the symbol.
	assert.deepEqual(regex.locations, [
		{ file: "host/src/host/patterns.ts", line: 15, symbol: "matchHostname" },
	]);
	assert.deepEqual(regex.evidenceQuotes, [
		"return pattern.test(hostname)",
		"diff drops the $ anchor",
		exactEvidence,
	]);

	const partition = await helper({
		sources: {
			"dedup-findings.main": dedup,
			"devil-advocate.item-001": {
				finding: { title: "Path boundary bypass in isPathInsideRoot" },
				verdict: "KEEP",
			},
			"devil-advocate.item-002": {
				finding: { title: "Regex anchor dropped in matchHostname" },
				verdict: "KEEP",
			},
		},
		options: { mode: "partition", dedupStage: "dedup-findings" },
	});
	assert.equal(partition.partitionSummary.keep, 2);
	// Identity evidence is code-preserved onto keep items, same as severity.
	const keepBoundary = partition.partitions.keep.find((k) =>
		k.title.includes("Path boundary"),
	);
	assert.equal(keepBoundary.file, "host/src/alpine/rootfs.ts");
	assert.ok(keepBoundary.locations.some((loc) => loc.line === 46));
	assert.ok(keepBoundary.locations.some((loc) => loc.line === 90));
	assert.ok(
		keepBoundary.evidenceQuotes.includes(
			"if (!isPathInsideRoot(target, root)) throw",
		),
	);
	const keepRegex = partition.partitions.keep.find((k) =>
		k.title.includes("Regex anchor"),
	);
	assert.deepEqual(keepRegex.locations, [
		{ file: "host/src/host/patterns.ts", line: 15, symbol: "matchHostname" },
	]);
	assert.deepEqual(keepRegex.evidenceQuotes, [
		"return pattern.test(hostname)",
		"diff drops the $ anchor",
		exactEvidence,
	]);
	assert.equal(
		partition.partitions.keep.some((finding) => "reviewerFinding" in finding),
		false,
	);

	const mergedPartition = await helper({
		sources: {
			"dedup-findings.main": {
				findings: [
					{
						id: "merge-001",
						findingId: "merge-001",
						rootCauseId: "root-merge-001",
						severity: "high",
						title: "Parser shared root failure alpha",
						file: "src/parser.ts",
						locations: [
							{ file: "src/parser.ts", line: 10, symbol: "parse" },
						],
						evidenceQuotes: ["common parser evidence"],
					},
					{
						id: "merge-002",
						findingId: "merge-002",
						rootCauseId: "root-merge-002",
						severity: "high",
						title: "Parser shared root failure beta",
						file: "src/parser.ts",
						locations: [
							{ file: "src/parser.ts", line: 10, symbol: "parse" },
						],
						evidenceQuotes: ["common parser evidence", exactEvidence],
					},
				],
			},
			"devil-advocate.item-merge-001": {
				finding: { title: "Parser shared root failure alpha" },
				verdict: "KEEP",
			},
			"devil-advocate.item-merge-002": {
				finding: { title: "Parser shared root failure beta" },
				verdict: "KEEP",
			},
		},
		options: { mode: "partition", dedupStage: "dedup-findings" },
	});
	assert.equal(mergedPartition.partitionSummary.mergedFindings, 1);
	assert.ok(
		mergedPartition.partitions.keep[0].evidenceQuotes.includes(exactEvidence),
	);
	assert.equal(
		mergedPartition.partitions.keep[0].evidenceQuotes.find(
			(quote) => quote.includes("keep spacing"),
		),
		exactEvidence,
	);

	const mutuallyCompoundPartition = await helper({
		sources: {
			"dedup-findings.main": {
				findings: [
					{
						id: "compound-001",
						findingId: "compound-001",
						rootCauseId: "root-compound-001",
						severity: "high",
						title: "startup failure async",
						file: "src/compound.ts",
						locations: [{ file: "src/compound.ts", line: 1 }],
						evidenceQuotes: ["EXACT-A"],
					},
					{
						id: "compound-002",
						findingId: "compound-002",
						rootCauseId: "root-compound-002",
						severity: "high",
						title: "cannot open durability",
						file: "src/compound.ts",
						locations: [{ file: "src/compound.ts", line: 1 }],
						evidenceQuotes: ["EXACT-B"],
					},
				],
			},
			"devil-advocate.item-compound-001": {
				finding: { title: "startup failure async" },
				verdict: "KEEP",
			},
			"devil-advocate.item-compound-002": {
				finding: { title: "cannot open durability" },
				verdict: "KEEP",
			},
		},
		options: { mode: "partition", dedupStage: "dedup-findings" },
	});
	assert.equal(mutuallyCompoundPartition.partitionSummary.keep, 2);
	assert.deepEqual(
		mutuallyCompoundPartition.partitions.keep.flatMap(
			(finding) => finding.evidenceQuotes,
		),
		["EXACT-A", "EXACT-B"],
	);

	const schemaDir = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"workflows",
		"deep-review",
		"schemas",
	);
	const dedupSchema = JSON.parse(
		readFileSync(
			join(schemaDir, "deep-review-dedup-control.schema.json"),
			"utf8",
		),
	);
	const partitionSchema = JSON.parse(
		readFileSync(
			join(schemaDir, "deep-review-partition-control.schema.json"),
			"utf8",
		),
	);
	const validDedup = validateJsonSchema(
		{ schema: "stage-control-v1", ...dedup },
		dedupSchema,
	);
	assert.equal(validDedup.valid, true, JSON.stringify(validDedup.issues));
	const validPartition = validateJsonSchema(
		{ schema: "stage-control-v1", ...partition },
		partitionSchema,
	);
	assert.equal(
		validPartition.valid,
		true,
		JSON.stringify(validPartition.issues),
	);
	const evidenceLessPartition = structuredClone({
		schema: "stage-control-v1",
		...partition,
	});
	evidenceLessPartition.partitions.keep[0].evidenceQuotes = [];
	const invalidPartition = validateJsonSchema(
		evidenceLessPartition,
		partitionSchema,
	);
	assert.equal(invalidPartition.valid, false);
	assert.ok(
		invalidPartition.issues.some(
			(issue) => issue.path === "$.partitions.keep[0].evidenceQuotes",
		),
	);
	const incompleteSupportNotePartition = structuredClone({
		schema: "stage-control-v1",
		...partition,
	});
	incompleteSupportNotePartition.supportNotes = [
		{
			title: "Missing support evidence",
			locations: [],
			evidenceQuotes: [],
		},
	];
	const invalidSupportNote = validateJsonSchema(
		incompleteSupportNotePartition,
		partitionSchema,
	);
	assert.equal(invalidSupportNote.valid, false);
	assert.ok(
		invalidSupportNote.issues.some((issue) =>
			issue.path.startsWith("$.supportNotes[0]"),
		),
	);
});

test("deep-review finding-pipeline opt-in batch planner flattens results with strict membership gates", async () => {
	const helperPath = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"workflows",
		"deep-review",
		"helpers",
		"finding-pipeline.mjs",
	);
	const helper = (
		await import(`${pathToFileURL(helperPath).href}?batch=${Date.now()}`)
	).default;
	const findings = [
		"Alpha runtime regression",
		"Beta authorization bypass",
		"Gamma data loss",
		"Delta cache poisoning",
		"Epsilon schema drift",
		"Alpha runtime regression",
	].map((title, index) => ({
		id: `F-${String(index + 1).padStart(3, "0")}`,
		findingId: `F-${String(index + 1).padStart(3, "0")}`,
		rootCauseId: `R-${String(index + 1).padStart(3, "0")}`,
		severity: index === 1 ? "critical" : "medium",
		title,
		file: `src/file-${index + 1}.ts`,
		locations: [{ file: `src/file-${index + 1}.ts`, line: index + 10 }],
		evidenceQuotes: [`quote-${index + 1}`],
	}));

	const batches = await helper({
		sources: { "dedup-findings.main": { findings } },
		options: {
			mode: "batch-devil-advocate",
			dedupStage: "dedup-findings",
			maxBatchSize: 3,
		},
	});
	assert.equal(batches.schema, "deep-review-devil-advocate-batches-v1");
	assert.equal(batches.batchCount, 2);
	assert.deepEqual(
		batches.batches.map((batch) => batch.findingIds),
		[
			["F-001", "F-002", "F-003"],
			["F-004", "F-005", "F-006"],
		],
	);

	const validRow = (findingId, title, verdict) => ({
		findingId,
		title,
		verdict,
		evidenceSourceType: "concrete_artifact",
		evidence: [`${findingId} evidence`],
		counterEvidence: [],
		recommendedAction: `Handle ${findingId}`,
	});
	const partition = await helper({
		sources: {
			"dedup-findings.main": { findings },
			"devil-advocate-batches.main": batches,
			"devil-advocate.dabatch-001": {
				schema: "deep-review-devil-advocate-batch-v2",
				digest: "batch one",
				results: [
					validRow("F-001", "Alpha runtime regression", "KEEP"),
					validRow("F-002", "Beta authorization bypass", "WEAKEN"),
					validRow("F-003", "Gamma data loss", "DROP"),
					validRow("F-999", "Out of batch", "KEEP"),
					{
						...validRow("F-998", "Extra row field", "KEEP"),
						unexpected: true,
					},
				],
			},
			"devil-advocate.dabatch-002": {
				schema: "deep-review-devil-advocate-batch-v2",
				digest: "batch two",
				results: [
					validRow("F-004", "Delta cache poisoning", "KEEP"),
					validRow("F-004", "Delta cache poisoning", "WEAKEN"),
					validRow("F-005", "Wrong epsilon title", "KEEP"),
					validRow("F-005", "Epsilon schema drift", "keep"),
					{
						findingId: "",
						title: "Malformed row",
						verdict: "KEEP",
						evidence: [],
						counterEvidence: [],
						recommendedAction: "",
					},
				],
			},
			"devil-advocate.dabatch-999": {
				schema: "deep-review-devil-advocate-batch-v2",
				digest: "unknown batch",
				results: [validRow("F-997", "Unknown batch row", "KEEP")],
			},
		},
		options: {
			mode: "partition",
			dedupStage: "dedup-findings",
			devilAdvocateBatchStage: "devil-advocate-batches",
		},
	});

	assert.deepEqual(
		partition.partitions.keep.map((finding) => finding.findingId),
		["F-001"],
	);
	assert.deepEqual(
		partition.partitions.weaken.map((finding) => finding.findingId),
		["F-002"],
	);
	assert.deepEqual(
		partition.partitions.drop.map((finding) => finding.findingId),
		["F-003"],
	);
	assert.equal(partition.partitionSummary.batchIntegrityIssues, 7);
	assert.equal(partition.partitionSummary.missingVerdicts, 1);
	assert.equal(partition.partitionSummary.needsHuman, 8);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"batch_result_finding_not_in_source_batch",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"duplicate_batch_result_for_finding",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason === "batch_result_title_mismatch",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"malformed_batch_result_invalid_verdict",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"malformed_batch_result_extra_fields",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"unknown_devil_advocate_batch_id",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.batchIntegrityIssue?.reason ===
				"malformed_batch_result_missing_findingId",
		),
	);
	assert.ok(
		partition.partitions.needsHuman.some(
			(finding) =>
				finding.findingId === "F-006" &&
				finding.title === "Alpha runtime regression" &&
				finding.note === "no devil-advocate verdict received for this finding",
		),
	);
});

